import { Sparkles } from "lucide-react";
import type { Translator } from "@app/i18n";
import { cn } from "../lib/cn";

/**
 * Notes generated by AI are active from the start; this small badge marks their provenance until a
 * person approves or edits them. Review is optional, so it never reads as a warning. Lists use the
 * compact badge; an object page uses the full one, which spells the provenance out.
 */
export function AiNoteBadge({
  t,
  status,
  humanProtected = false,
  variant = "compact",
  className
}: {
  t: Translator;
  /** The note status; only a note that is still `active` (never reviewed) is marked. */
  status: string | null | undefined;
  /**
   * A person edited the note: an edit keeps it `active`, but it is no longer AI-generated text, so
   * the surface shows its protected indication instead.
   */
  humanProtected?: boolean;
  variant?: "compact" | "full";
  className?: string;
}) {
  if (status !== "active" || humanProtected) return null;
  if (variant === "full")
    return (
      <span
        title={t("knowledge.notes.aiBadgeHint")}
        data-testid="ai-note-badge"
        className={cn(
          "inline-flex h-5 items-center gap-1 rounded-full bg-soft px-2 text-xs font-medium text-secondary-foreground",
          className
        )}
      >
        <Sparkles className="size-3" aria-hidden="true" />
        <span aria-hidden="true">{t("knowledge.notes.aiBadgeLong")}</span>
        <span className="sr-only">{t("knowledge.notes.aiBadgeHint")}</span>
      </span>
    );
  return (
    <span
      title={t("knowledge.notes.aiBadgeHint")}
      data-testid="ai-note-badge"
      className={cn(
        "inline-flex items-center gap-1 rounded-full border border-border bg-accent-soft px-1.5 py-0.5 text-xs font-semibold text-accent",
        className
      )}
    >
      <Sparkles className="h-3 w-3" aria-hidden="true" />
      <span aria-hidden="true">{t("knowledge.notes.aiBadge")}</span>
      <span className="sr-only">{t("knowledge.notes.aiBadgeHint")}</span>
    </span>
  );
}
